// ===========================================================================
// Battery 3: `checkpointChronologyCases`.
// ===========================================================================
#[test]
fn checkpoint_chronology_cases_match_ts() {
    let vectors = load_vectors();
    let settings = settings(&vectors);
    let cases = vectors["checkpointChronologyCases"]
        .as_array()
        .expect("checkpointChronologyCases array");
    assert!(
        !cases.is_empty(),
        "expected at least one checkpointChronologyCase"
    );

    for case in cases {
        let case_id = get_str(case, "caseId");
        let pieces = decode_prepared_pieces(&case["pieces"]);
        let sheet = decode_sheet(&case["sheet"]);
        let mut geometry_cache = GeometryCacheStore::new();

        let mut producer_roles: Vec<String> = Vec::new();
        let mut next_piece_indices: Vec<f64> = Vec::new();
        let mut on_checkpoint = |checkpoint: &irregular_nesting_native::search::strict_decoder::IntrinsicStrictDirectCheckpoint,
                                  _control: Option<&mut dyn irregular_nesting_native::nfp_ifp::NfpIfpControl>,
                                  _geometry_cache: &mut GeometryCacheStore|
         -> Result<(), SharedArchiveError> {
            producer_roles.push(checkpoint.producer_role.clone());
            next_piece_indices.push(checkpoint.next_piece_index);
            Ok(())
        };
        let mut options = IntrinsicSharedArchivePortfolioOptions {
            maximum_direct_runtime_ms: Some(15000.0),
            canonical_grid_completed_piece_quantum: Some(1.0),
            on_canonical_grid_checkpointed: Some(&mut on_checkpoint),
            ..Default::default()
        };

        let runs = run_intrinsic_shared_archive_direct_portfolio(
            &sheet,
            &pieces,
            &mut options,
            None,
            &settings,
            &mut geometry_cache,
        )
        .unwrap_or_else(|err| panic!("case {case_id} failed: {err:?}"));

        let expected_fire_count: f64 = get_str(case, "checkpointFireCount")
            .parse()
            .expect("checkpointFireCount is a decimal string");
        assert_eq!(
            producer_roles.len() as f64,
            expected_fire_count,
            "{case_id}: checkpoint fire count"
        );
        let expected_roles: Vec<String> = case["checkpointProducerRoles"]
            .as_array()
            .expect("checkpointProducerRoles array")
            .iter()
            .map(|v| v.as_str().expect("role is a string").to_string())
            .collect();
        assert_eq!(
            producer_roles, expected_roles,
            "{case_id}: checkpoint producer roles"
        );
        let expected_indices: Vec<f64> = case["checkpointNextPieceIndices"]
            .as_array()
            .expect("checkpointNextPieceIndices array")
            .iter()
            .map(|v| parse_f64_bits(v.as_str().expect("index is a hex string")))
            .collect();
        assert_eq!(
            next_piece_indices.len(),
            expected_indices.len(),
            "{case_id}: checkpoint next-piece-index count"
        );
        for (actual, expected) in next_piece_indices.iter().zip(expected_indices.iter()) {
            assert_eq!(
                actual.to_bits(),
                expected.to_bits(),
                "{case_id}: checkpoint next-piece-index"
            );
        }

        assert_runs_eq(&runs, &case["directRuns"], &format!("{case_id}.directRuns"));
        assert_runs_eq(
            &runs,
            &case["groundTruthDirectRuns"],
            &format!("{case_id}: quantum-resumed result must equal the unbounded ground truth"),
        );
    }
}

// ===========================================================================
// Battery 4: `admissionCases`.
// ===========================================================================
#[test]
fn admission_cases_match_ts() {
    let vectors = load_vectors();
    let settings = settings(&vectors);
    let cases = vectors["admissionCases"]
        .as_array()
        .expect("admissionCases array");
    assert!(!cases.is_empty(), "expected at least one admissionCase");

    for case in cases {
        let case_id = get_str(case, "caseId");
        let kind = get_str(case, "kind");
        match kind {
            "illegal-no-fit" => {
                // Documentary cross-reference into `fullPortfolioCases`,
                // already independently reconstructed and asserted by
                // `full_portfolio_cases_match_ts`. Just confirm the
                // recorded rejection shape itself: sheetless archive
                // non-empty (direct roles completed sheetlessly), fitting
                // archive empty (nothing legally fits the 1x1 sheet).
                let retained = case["retainedHashes"]
                    .as_array()
                    .expect("retainedHashes array");
                assert!(
                    retained.is_empty(),
                    "{case_id}: expected empty fitting archive"
                );
                let input = case["inputEndpointHashes"]
                    .as_array()
                    .expect("inputEndpointHashes array");
                assert!(
                    !input.is_empty(),
                    "{case_id}: expected a non-empty sheetless archive"
                );
            }
            "duplicate" => {
                let pieces = decode_prepared_pieces(&case["pieces"]);
                let sheet = decode_sheet(&case["sheet"]);
                let mut geometry_cache = GeometryCacheStore::new();
                let mut options = IntrinsicSharedArchivePortfolioOptions {
                    maximum_direct_runtime_ms: Some(15000.0),
                    ..Default::default()
                };
                let runs = run_intrinsic_shared_archive_direct_portfolio(
                    &sheet,
                    &pieces,
                    &mut options,
                    None,
                    &settings,
                    &mut geometry_cache,
                )
                .unwrap_or_else(|err| panic!("case {case_id} failed: {err:?}"));
                let endpoints: Vec<IntrinsicSharedArchiveEndpoint> =
                    runs.into_iter().filter_map(|run| run.endpoint).collect();
                assert_eq!(
                    endpoints.len(),
                    3,
                    "{case_id}: expected 3 completed direct endpoints"
                );
                let retained = retain_ranked_shared_archive(&endpoints);
                let expected_roles: Vec<String> = case["retainedRoles"]
                    .as_array()
                    .expect("retainedRoles array")
                    .iter()
                    .map(|v| v.as_str().expect("role is a string").to_string())
                    .collect();
                let actual_roles: Vec<String> = retained.iter().map(|e| e.role.clone()).collect();
                assert_eq!(actual_roles, expected_roles, "{case_id}: retained roles");
                assert_eq!(
                    retained.len(),
                    1,
                    "{case_id}: expected exactly one retained duplicate"
                );
            }
            "hash-mismatch" => {
                let pieces = decode_prepared_pieces(&case["pieces"]);
                let sheet = decode_sheet(&case["sheet"]);
                let mut geometry_cache = GeometryCacheStore::new();
                let mut options = IntrinsicSharedArchivePortfolioOptions {
                    maximum_direct_runtime_ms: Some(15000.0),
                    ..Default::default()
                };
                let runs = run_intrinsic_shared_archive_direct_portfolio(
                    &sheet,
                    &pieces,
                    &mut options,
                    None,
                    &settings,
                    &mut geometry_cache,
                )
                .unwrap_or_else(|err| panic!("case {case_id} failed: {err:?}"));
                let mut endpoint = runs
                    .into_iter()
                    .find_map(|run| run.endpoint)
                    .unwrap_or_else(|| panic!("{case_id}: expected a completed endpoint"));
                endpoint.sheetless_canonical_geometry_hash =
                    format!("{}-corrupted", endpoint.sheetless_canonical_geometry_hash);
                let retained = retain_ranked_shared_archive(std::slice::from_ref(&endpoint));
                assert!(
                    retained.is_empty(),
                    "{case_id}: hash-mismatched endpoint must be rejected"
                );
                let expected_retained = case["retainedHashes"]
                    .as_array()
                    .expect("retainedHashes array");
                assert!(
                    expected_retained.is_empty(),
                    "{case_id}: expected empty recorded retainedHashes"
                );
            }
            "incomplete" => {
                let pieces = decode_prepared_pieces(&case["pieces"]);
                let sheet = decode_sheet(&case["sheet"]);
                let remaining_piece = pieces
                    .first()
                    .cloned()
                    .unwrap_or_else(|| panic!("{case_id}: expected at least one piece"));
                let state = IrregularBeamState::empty(vec![remaining_piece]);
                let constructed = IntrinsicStrictConstructResult {
                    state: Arc::clone(&state),
                    step_trace: Vec::new(),
                    gap_fill_evidence: Vec::new(),
                    candidate_evaluation_count: Some(3.0),
                    truncation_reason: None,
                    pause_reason: None,
                    checkpoint: None,
                    phase_timings: None,
                    runtime_ms: 5.0,
                };
                let run = normalize_intrinsic_shared_archive_constructed_run(
                    NormalizeIntrinsicSharedArchiveConstructedRunInput {
                        sheet: sheet.clone(),
                        role: "canonical-grid".to_string(),
                        source_id: None,
                        requested_candidate_evaluations: None,
                        constructed,
                    },
                );
                assert_eq!(
                    run.status,
                    decode_status(get_str(case, "normalizedRunStatus")),
                    "{case_id}: normalizedRunStatus"
                );
                assert_eq!(
                    run.endpoint.is_some(),
                    get_bool(case, "normalizedRunHasEndpoint"),
                    "{case_id}: normalizedRunHasEndpoint"
                );

                let direct_endpoint = make_intrinsic_shared_archive_endpoint(
                    MakeIntrinsicSharedArchiveEndpointInput {
                        sheet: &sheet,
                        role: "canonical-grid".to_string(),
                        source_id: None,
                        state,
                        runtime_ms: Some(5.0),
                    },
                );
                assert!(
                    direct_endpoint.is_none(),
                    "{case_id}: make_intrinsic_shared_archive_endpoint must return None for a state with remaining pieces"
                );
            }
            other => panic!("{case_id}: unrecognized admission case kind {other}"),
        }
    }
}

